# Oracle probe (L11.9) — a trap that carries a message but no exception class cannot be caught
# (Gap R.25, ADR 0214). Each of these arms used to be dead code and the exception used to leak out
# as a bare sentence; they now raise what CPython raises. The interpreter and CPython agree on all
# five lines. The compiled backend answers the attribute case with a value instead of trapping
# (Gap R.19) and refuses the others at compile time, so the leg does not complete.
class P:
    pass

p = P()

try:
    print(p.nope)
except AttributeError:
    print("attr ok")

try:
    print(int("abc"))
except ValueError:
    print("value ok")

try:
    a, b = [1]
except ValueError:
    print("unpack ok")

try:
    x = 5
    x()
except TypeError:
    print("call ok")

try:
    print(len(5))
except TypeError:
    print("len ok")

# Oracle probe (L11.9) — an operator applied to operands it cannot apply used to answer a
# number: `print("a" * "b")` printed 1099516870662 and exited 0 (Gap R.26, ADR 0215). Each
# arm below is the exception CPython raises, with CPython's wording; the interpreter and
# CPython agree line for line. The compiled backend refuses most of these at compile time,
# but answers `1 + None` with a value (roadmap Gap R.27), so the compiled leg is absent.
try:
    print("a" * "b")
except TypeError:
    print("mul-str ok")

try:
    print(1 - "a")
except TypeError:
    print("sub ok")

try:
    print("a" / 2)
except TypeError:
    print("div ok")

try:
    print(1 + None)
except TypeError:
    print("none ok")

try:
    print([1] + 1)
except TypeError:
    print("concat ok")

try:
    print("a" < 1)
except TypeError:
    print("order ok")

print("done")
